import { useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import { ProjectCard } from '@/shared/ui/ProjectCard'
import { CreateProjectTile } from '@/shared/ui/CreateProjectTile'
import { CreateProjectModal } from './CreateProjectModal'
import { useIdentity } from '@/app/providers/IdentityProvider'
import { projectsService } from '@/integrations/supabase/projects'
import { ChevronDown, RotateCcw, Search } from 'lucide-react'
import { clsx } from 'clsx'

type Tab = 'all' | 'collab'
type Sort = 'recent' | 'name' | 'updated'

export function ProjectsPage() {
  const navigate = useNavigate()
  const [showCreate, setShowCreate] = useState(false)
  const [tab, setTab] = useState<Tab>('all')
  const [sort, setSort] = useState<Sort>('recent')
  const [sortOpen, setSortOpen] = useState(false)
  const { activeWorkspace, centralUser } = useIdentity()
  const workplaceId = activeWorkspace?.id ?? ''
  const centralUserId = centralUser?.id ?? ''

  const { data: projects = [], isLoading, refetch, isFetching } = useQuery({
    queryKey: ['projects', workplaceId, centralUserId],
    queryFn: () => projectsService.listProjects(workplaceId, centralUserId),
    enabled: !!workplaceId && !!centralUserId,
  })

  const visible = useMemo(() => {
    const filtered = projects.filter((p) =>
      tab === 'all' ? p.roleForCurrentUser === 'owner' : p.roleForCurrentUser !== 'owner',
    )
    const sorted = [...filtered].sort((a, b) => {
      if (sort === 'name') return a.title.localeCompare(b.title)
      if (sort === 'updated') return b.updatedAt.localeCompare(a.updatedAt)
      return b.createdAt.localeCompare(a.createdAt)
    })
    return sorted
  }, [projects, tab, sort])

  return (
    <div className="h-full overflow-y-auto bg-[hsl(80_6%_95%)]">
      <div className="max-w-7xl mx-auto px-8 py-8">
        {/* Header */}
        <div className="flex items-center justify-between mb-8 gap-4 flex-wrap">
          <h1 className="text-3xl font-semibold text-foreground">All projects</h1>
          <div className="flex items-center gap-3">
            <div className="flex items-center bg-card rounded-full p-1 border border-border">
              {([
                { id: 'all' as const, label: 'All projects' },
                { id: 'collab' as const, label: 'Collaborations' },
              ]).map((t) => (
                <button
                  key={t.id}
                  onClick={() => setTab(t.id)}
                  className={clsx(
                    'px-4 py-1.5 text-sm rounded-full transition-colors',
                    tab === t.id ? 'bg-foreground text-background' : 'text-muted-foreground hover:text-foreground',
                  )}
                >
                  {t.label}
                </button>
              ))}
            </div>
            <div className="relative">
              <button
                onClick={() => setSortOpen((o) => !o)}
                className="flex items-center gap-2 px-4 py-2 text-sm bg-card border border-border rounded-full hover:border-foreground/30"
              >
                Sort by
                <span className="w-2 h-2 rounded-full bg-accent" />
                <ChevronDown size={14} />
              </button>
              {sortOpen && (
                <div className="absolute right-0 mt-2 w-44 rounded-xl border border-border bg-card shadow-lg z-10 overflow-hidden">
                  {([
                    { id: 'recent' as const, label: 'Newest first' },
                    { id: 'updated' as const, label: 'Recently updated' },
                    { id: 'name' as const, label: 'Name (A–Z)' },
                  ]).map((o) => (
                    <button
                      key={o.id}
                      onClick={() => { setSort(o.id); setSortOpen(false) }}
                      className={clsx(
                        'w-full text-left px-4 py-2 text-sm hover:bg-muted',
                        sort === o.id && 'text-accent font-medium',
                      )}
                    >
                      {o.label}
                    </button>
                  ))}
                </div>
              )}
            </div>
            <button
              onClick={() => refetch()}
              disabled={isFetching}
              className="w-10 h-10 rounded-full bg-accent text-accent-foreground flex items-center justify-center hover:opacity-90 disabled:opacity-50"
              aria-label="Refresh"
            >
              <RotateCcw size={16} className={isFetching ? 'animate-spin' : ''} />
            </button>
            <button
              onClick={() => navigate('/app/search')}
              className="w-10 h-10 rounded-full bg-card border border-border flex items-center justify-center hover:border-foreground/30"
              aria-label="Search"
            >
              <Search size={16} />
            </button>
          </div>
        </div>

        {/* Grid */}
        {!workplaceId ? (
          <p className="text-sm text-muted-foreground">Preparing your workspace…</p>
        ) : isLoading ? (
          <p className="text-sm text-muted-foreground">Loading projects…</p>
        ) : (
          <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            <CreateProjectTile onClick={() => setShowCreate(true)} />
            {visible.map((p) => (
              <ProjectCard key={p.id} project={p} onClick={() => navigate(`/app/project/${p.id}/organiser`)} />
            ))}
            {visible.length === 0 && tab === 'collab' && (
              <div className="col-span-full text-sm text-muted-foreground text-center py-12">
                No collaborations yet.
              </div>
            )}
          </div>
        )}
      </div>

      {showCreate && <CreateProjectModal onClose={() => { setShowCreate(false); refetch() }} />}
    </div>
  )
}
